/**
 * Millisecond and 60 FPS frame-accurate timing record for a single word.
 * Generated by the EdgeTTS asset harvester (scripts/harvest/voice.py).
 */
export interface HarvestWordTiming {
  index: number;
  word: string;
  token: string;
  startTime: number;
  endTime: number;
  startMs: number;
  endMs: number;
  durationMs: number;
  startFrame: number;
  endFrame: number;
  durationFrames: number;
}

/**
 * Audio metadata produced during voice harvesting.
 */
export interface HarvestAudioMeta {
  file: string;
  wavAvailable?: boolean;
  voice: string;
  rate?: string;
  durationSeconds: number;
  durationFrames: number;
}

/**
 * B-Roll stock footage metadata produced during Pexels harvesting.
 */
export interface HarvestBRollMeta {
  query?: string;
  aspect?: string;
  file?: string | null;
  found?: boolean;
  message?: string;
  duration?: number;
  width?: number;
  height?: number;
  creator?: string;
  sourcePage?: string;
  assetId?: string;
  cachedAt?: number;
}

/**
 * Unified project harvest manifest contract.
 */
export interface HarvestManifest {
  project: string;
  aspect: '16:9' | '9:16' | string;
  fps: number;
  timestamp?: number;
  audio?: HarvestAudioMeta | null;
  broll?: HarvestBRollMeta | null;
  words: HarvestWordTiming[];
}

/**
 * Normalizes an array of raw word timings, guaranteeing sorted order,
 * positive frame intervals, and optional frame re-projection for target FPS.
 */
export function normalizeHarvestWords(
  rawWords: readonly HarvestWordTiming[] | null | undefined,
  targetFps: number = 60
): HarvestWordTiming[] {
  if (!rawWords || !Array.isArray(rawWords) || rawWords.length === 0) {
    return [];
  }

  const sorted = [...rawWords].sort((a, b) => a.startTime - b.startTime);

  return sorted.map((w, idx) => {
    const startSec = Math.max(0, Number(w.startTime) || 0);
    const endSec = Math.max(startSec, Number(w.endTime) || startSec);
    const rawStartFrame = Math.round(startSec * targetFps);
    const rawEndFrame = Math.round(endSec * targetFps);
    const durationFrames = Math.max(1, rawEndFrame - rawStartFrame);
    const endFrame = Math.max(rawStartFrame + durationFrames, rawEndFrame);

    return {
      index: idx,
      word: String(w.word || '').trim(),
      token: String(w.token || w.word || '').trim(),
      startTime: startSec,
      endTime: endSec,
      startMs: Math.round(startSec * 1000),
      endMs: Math.round(endSec * 1000),
      durationMs: Math.max(0, Math.round((endSec - startSec) * 1000)),
      startFrame: rawStartFrame,
      endFrame,
      durationFrames,
    };
  });
}

/**
 * Finds the exact active word spoken at the specified frame.
 * For adjacent words, the boundary frame marks the start of the next word.
 * Returns null if the frame is before the first word, in a silence pause, or after narration ends.
 */
export function getWordAtFrame(
  words: readonly HarvestWordTiming[] | null | undefined,
  currentFrame: number
): HarvestWordTiming | null {
  if (!words || words.length === 0) {
    return null;
  }

  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    const isLast = i === words.length - 1;
    const isWithin = isLast
      ? currentFrame >= w.startFrame && currentFrame <= w.endFrame
      : currentFrame >= w.startFrame && currentFrame < w.endFrame;

    if (isWithin) {
      return w;
    }
  }

  return null;
}

/**
 * Robustly resolves the active or most recent word index for sliding subtitle windows.
 * Prevents subtitle UI jumping back to frame 0 during pauses between words or after speech.
 */
export function getActiveOrLastWordIndex(
  words: readonly HarvestWordTiming[] | null | undefined,
  currentFrame: number
): { activeIndex: number; pivotIndex: number; isBefore: boolean; isAfter: boolean } {
  if (!words || words.length === 0) {
    return { activeIndex: -1, pivotIndex: -1, isBefore: true, isAfter: true };
  }

  if (currentFrame < words[0].startFrame) {
    return { activeIndex: -1, pivotIndex: 0, isBefore: true, isAfter: false };
  }

  const lastWord = words[words.length - 1];
  if (currentFrame > lastWord.endFrame) {
    return { activeIndex: -1, pivotIndex: words.length - 1, isBefore: false, isAfter: true };
  }

  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    const isLast = i === words.length - 1;
    const isWithin = isLast
      ? currentFrame >= w.startFrame && currentFrame <= w.endFrame
      : currentFrame >= w.startFrame && currentFrame < w.endFrame;

    if (isWithin) {
      return { activeIndex: i, pivotIndex: i, isBefore: false, isAfter: false };
    }

    if (i < words.length - 1) {
      const nextWord = words[i + 1];
      if (currentFrame >= w.endFrame && currentFrame < nextWord.startFrame) {
        return { activeIndex: -1, pivotIndex: i, isBefore: false, isAfter: false };
      }
    }
  }

  return { activeIndex: -1, pivotIndex: 0, isBefore: false, isAfter: false };
}

/**
 * Calculates a clamped 0.0 -> 1.0 progress for a word across its active frame interval.
 */
export function calculateWordProgress(
  word: HarvestWordTiming,
  currentFrame: number
): number {
  if (!word || word.durationFrames <= 0) return 0;
  if (currentFrame < word.startFrame) return 0;
  if (currentFrame >= word.endFrame) return 1;

  const elapsed = currentFrame - word.startFrame;
  return Math.min(1, Math.max(0, elapsed / word.durationFrames));
}

/**
 * Returns active and upcoming words within a specified frame window around currentFrame.
 */
export function getActiveWordsInWindow(
  words: readonly HarvestWordTiming[] | null | undefined,
  currentFrame: number,
  windowFrames: number = 30
): HarvestWordTiming[] {
  if (!words || words.length === 0) {
    return [];
  }

  const windowStart = currentFrame - windowFrames;
  const windowEnd = currentFrame + windowFrames;

  return words.filter(
    (w) => w.endFrame >= windowStart && w.startFrame <= windowEnd
  );
}

/**
 * Pure deterministic Ken Burns camera trajectory for background video/image.
 * Scales gradually from 1.0 up to maxScale with smooth cubic ease, zero jitter.
 */
export function computeHarvestKenBurns(
  frame: number,
  durationFrames: number,
  maxScale: number = 1.08,
  fadeInFrames: number = 12
): { scale: number; opacity: number } {
  if (durationFrames <= 0) {
    return { scale: 1.0, opacity: 1.0 };
  }
  const safeFrame = Math.max(0, frame);
  const t = Math.min(1.0, safeFrame / durationFrames);
  // Smooth cubic ease-out
  const progress = 1.0 - Math.pow(1.0 - t, 3);
  const scale = 1.0 + (maxScale - 1.0) * progress;

  // Gentle fade-in over initial frames
  const fadeIn = fadeInFrames > 0
    ? Math.min(1.0, Math.max(0.0, frame / fadeInFrames))
    : 1.0;

  return { scale, opacity: fadeIn };
}
